let opsPage='orders',orderFilter='Active',productQuery='';
function openOps(page){opsPage=page;renderOps()}
function refreshStore(){try{const latest=JSON.parse(localStorage.getItem('nook-demo-v1'));if(latest)state=latest}catch{}}
function renderOps(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===opsPage));if(opsPage==='orders')renderOrders();if(opsPage==='products')renderProducts();if(opsPage==='settings')renderSettings();if(opsPage==='qr')renderQR()}
function renderOrders(){const orders=state.orders.filter(o=>orderFilter==='All'||(orderFilter==='Active'?o.status<3:statuses[o.status]===orderFilter));$('#opsMain').innerHTML=`<div class="heading"><div><h1>Every order, cared for.</h1><p>Pick, pack, and send a little good to your neighbours.</p></div><button class="secondary" onclick="addSampleOrder()">+ Sample order</button></div><div class="stats">${[['New orders',state.orders.filter(o=>o.status===0).length],['Packing',state.orders.filter(o=>o.status===1).length],['Out for delivery',state.orders.filter(o=>o.status===2).length],['Completed',state.orders.filter(o=>o.status===3).length]].map(([label,n])=>`<div class="panel"><small>${label}</small><strong>${n}</strong></div>`).join('')}</div><div class="ops-toolbar"><div class="ops-tabs">${['Active','Confirmed','Packing','Out for delivery','Delivered','All'].map(s=>`<button class="${s===orderFilter?'active':''}" onclick="orderFilter='${s}';renderOrders()">${s==='Confirmed'?'New':s}</button>`).join('')}</div><small>${orders.length} orders</small></div><div class="ops-orders">${orders.map(o=>`<article class="ops-card"><div class="row"><strong>${o.id}</strong><span class="status-tag">${statuses[o.status]}</span></div><h3>${esc(o.customer?.name||'Demo customer')}</h3><p>${esc(o.address.line)}<br>${o.address.distance} km · ${new Date(o.created).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</p><div class="row"><span>${o.items.reduce((s,i)=>s+i.qty,0)} items · ${esc(o.payment)}</span><strong>${money(o.total)}</strong></div><details><summary>View items & customer</summary>${o.items.map(i=>`<div class="row"><span>${i.qty} × ${esc(i.name)}</span><strong>${money(i.qty*i.price)}</strong></div>`).join('')}<p>Mobile: ${esc(o.customer?.phone||'Not supplied')}</p></details>${o.status<3?`<button class="primary" onclick="advanceOrder('${o.id}')">${['Accept & start packing','Mark out for delivery','Mark delivered'][o.status]} →</button>`:'<div class="notice">✓ Delivered to the customer</div>'}</article>`).join('')}</div>${!orders.length?'<div class="empty"><h3>No orders here yet</h3><p>Place an order in the customer app or add a sample order to try the workflow.</p><a class="secondary" href="/" target="_blank">Open customer app ↗</a></div>':''}`}
function advanceOrder(id){refreshStore();const o=state.orders.find(o=>o.id===id);if(!o||o.status>=3)return;o.status++;save();renderOps();toast('Order '+statuses[o.status].toLowerCase())}
function addSampleOrder(){refreshStore();const p=state.products.find(p=>p.stock>0);if(!p)return toast('Restock a product first');p.stock--;state.orders.unshift({id:'NK-'+Date.now().toString(36).toUpperCase(),created:new Date().toISOString(),customer:{name:'Sample customer',phone:'9876543210'},items:[{name:p.name,qty:1,price:p.price}],total:p.price+(p.price>=299?0:25),address:{label:'Home',line:'12, 2nd Main, Indiranagar, Bengaluru',distance:2.4},payment:'Cash on delivery',status:0});save();orderFilter='Active';renderOps();toast('Sample order added; stock adjusted')}
function renderProducts(){const products=state.products.filter(p=>`${p.name} ${p.category}`.toLowerCase().includes(productQuery.toLowerCase()));$('#opsMain').innerHTML=`<div class="heading"><div><h1>A well-stocked neighbourhood.</h1><p>${state.products.length} products · ${state.products.filter(p=>p.stock===0).length} sold out · ${state.products.filter(p=>p.stock>0&&p.stock<6).length} low stock</p></div><button class="primary" onclick="newProduct()">+ Add product</button></div><div class="ops-toolbar"><input type="search" aria-label="Search inventory" placeholder="Search products or category" value="${esc(productQuery)}" onchange="productQuery=this.value;renderProducts()"></div><section class="panel table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price ₹</th><th>Stock</th><th>Availability</th></tr></thead><tbody>${products.map(p=>`<tr><td>${p.emoji} ${esc(p.name)}<br><small>${esc(p.unit)}</small></td><td>${esc(p.category)}</td><td><input type="number" min="1" max="10000" step="1" value="${p.price}" aria-label="Price for ${esc(p.name)}" onchange="storeEdit(${p.id},'price',this)"></td><td><input type="number" min="0" max="1000" step="1" value="${p.stock}" aria-label="Stock for ${esc(p.name)}" onchange="storeEdit(${p.id},'stock',this)"></td><td><span class="status-tag">${!p.stock?'Sold out':p.stock<6?'Low stock':'In stock'}</span></td></tr>`).join('')}</tbody></table>${products.length?'':'<div class="empty">No matching products.</div>'}</section>`}
function storeEdit(id,key,input){if(!input.checkValidity()){input.reportValidity();input.value=state.products[id][key];return}refreshStore();state.products[id][key]=Number(input.value);if(key==='price')state.products[id].mrp=Math.max(state.products[id].mrp,Number(input.value));save();renderProducts();toast('Product updated in customer app')}
function newProduct(){modal('Add an essential',`<form onsubmit="createProduct(event)"><label class="field">Product name<input name="name" required maxlength="70"></label><label class="field">Pack size<input name="unit" required maxlength="30" placeholder="e.g. 500 g"></label><label class="field">Category<select name="category">${['Fruit & veg','Dairy & eggs','Bakery','Snacks','Drinks','Pantry','Home care'].map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Price (₹)<input name="price" type="number" min="1" max="10000" step="1" required></label><label class="field">Opening stock<input name="stock" type="number" min="0" max="1000" step="1" required></label><button class="primary full">Add product</button></form>`)}
function createProduct(e){e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim(),unit=String(f.get('unit')||'').trim(),price=Number(f.get('price')),stock=Number(f.get('stock')),category=String(f.get('category'));if(!name||!unit||!Number.isInteger(price)||price<1||price>10000||!Number.isInteger(stock)||stock<0||stock>1000)return toast('Check the product details');refreshStore();state.products.push({id:state.products.length,name,unit,category,price,mrp:price,stock,emoji:'🛍️'});save();$('#dialog').close();renderProducts();toast('Product added')}
function renderSettings(){$('#opsMain').innerHTML=`<div class="heading"><div><h1>Keep it close to home.</h1><p>Set your delivery neighbourhood.</p></div></div><section class="panel" style="max-width:640px"><h2>Delivery settings</h2><form onsubmit="saveOpsRadius(event)"><label class="field">Service radius (km)<input name="radius" type="number" min="0.1" max="100" step="0.1" required value="${state.radius}"></label><button class="primary">Save settings</button></form><p>Customers outside this radius cannot checkout. Demo distances are simulated. Delivery is ₹25, free from ₹299.</p><div class="notice">This operations app is a presentation demo, not a secured staff system. Data is local to this browser. A production app needs staff authentication and shared backend storage.</div></section>`}
function saveOpsRadius(e){e.preventDefault();const radius=Number(new FormData(e.target).get('radius'));if(!Number.isFinite(radius)||radius<.1||radius>100)return;refreshStore();state.radius=radius;save();toast('Delivery radius saved')}
function renderQR(){$('#opsMain').innerHTML=`<div class="heading"><div><h1>Your store. On their home screen.</h1><p>A counter-ready QR for your customer app.</p></div></div><div class="qr-layout"><div class="qr-poster"><span class="brand">nook<span>●</span></span><h2>Your neighbourhood,<br>one scan away.</h2><img src="/customer-app-qr.png" alt="QR code opening the Nook customer app installation page"><p>Scan to open & install the customer app</p></div><section class="panel"><h2>Let customers take Nook home</h2><p>Print this QR and place it at the billing counter. It opens the customer app installation page on their phone.</p><a class="primary" href="/customer-app-qr.png" download="nook-customer-app-qr.png">Download QR image ↓</a><p><a class="secondary" href="/install/" target="_blank">Preview install page ↗</a></p><h3>How installation works</h3><p>On supported Android browsers, tap Install app. On iPhone, use Safari → Share → Add to Home Screen.</p><div class="notice">This installs a web app, not an APK or an App Store download. The hosted preview may require the owner's sign-in while sharing remains private.</div></section></div>`}
view='admin';renderOps();
